package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

type EvalResult struct {
	Value        Value
	OutputFormat string
	SourcePath   string
}

var (
	loadRe    = regexp.MustCompile(`load\("((?:[^"\\]|\\.)*)"\)`)
	strenvRe  = regexp.MustCompile(`strenv\(([A-Za-z_][A-Za-z0-9_]*)\)`)
	envRe     = regexp.MustCompile(`env\(([A-Za-z_][A-Za-z0-9_]*)\)`)
	selectRe  = regexp.MustCompile(`^\s*select\(\s*\$__yq_fileIndex\s*==\s*([0-9]+)\s*\)\s*\*\s*select\(\s*\$__yq_fileIndex\s*==\s*([0-9]+)\s*\)\s*$`)
	ireduceRe = regexp.MustCompile(`(?s)^\s*\.\s+as\s+\$([A-Za-z_][A-Za-z0-9_]*)\s+ireduce\s*\((.*)\)\s*$`)
)

func evaluate(opts options, expr string, docs []InputDoc) ([]EvalResult, error) {
	if opts.nullInput {
		return evalNullInput(opts, expr)
	}
	if opts.command == "eval-all" {
		return evalAll(opts, expr, docs)
	}
	return evalSequence(opts, expr, docs)
}

func evalNullInput(opts options, expr string) ([]EvalResult, error) {
	jqExpr, err := preprocessExpression(expr, opts)
	if err != nil {
		return nil, err
	}
	jqExpr = replaceMetaIdentifiers(jqExpr)
	outFmt, _ := resolvedOutputFormat(opts, normalizeFormat(opts.inputFormat), "-")
	results, err := runJQProgram(jqExpr, nil, true)
	if err != nil {
		return nil, err
	}
	out := make([]EvalResult, 0, len(results))
	for _, val := range results {
		out = append(out, EvalResult{Value: val, OutputFormat: outFmt, SourcePath: "-"})
	}
	return out, nil
}

func evalSequence(opts options, expr string, docs []InputDoc) ([]EvalResult, error) {
	jqExpr, err := preprocessExpression(expr, opts)
	if err != nil {
		return nil, err
	}
	jqExpr = replaceMetaIdentifiers(jqExpr)
	var out []EvalResult
	for _, doc := range docs {
		prog := fmt.Sprintf("%d as $__yq_fileIndex | %s", doc.FileIndex, jqExpr)
		in, warn, err := prepareInputBytes(doc.Value, opts, doc.InputFormat, doc.SourcePath)
		if err != nil {
			return nil, err
		}
		if warn != "" {
			fmt.Fprintln(os.Stderr, warn)
		}
		values, err := runJQProgram(prog, in, false)
		if err != nil {
			return nil, err
		}
		outFmt, _ := resolvedOutputFormat(opts, doc.InputFormat, doc.SourcePath)
		for _, val := range values {
			out = append(out, EvalResult{Value: val, OutputFormat: outFmt, SourcePath: doc.SourcePath})
		}
	}
	return out, nil
}

func evalAll(opts options, expr string, docs []InputDoc) ([]EvalResult, error) {
	jqExpr, err := preprocessExpression(expr, opts)
	if err != nil {
		return nil, err
	}
	jqExpr = replaceMetaIdentifiers(jqExpr)
	jqExpr, err = translateEvalAll(jqExpr)
	if err != nil {
		return nil, err
	}
	wrapped := &OrderedMap{}
	_ = wrapped
	all := make([]Value, 0, len(docs))
	for _, doc := range docs {
		all = append(all, &OrderedMap{Entries: []Entry{
			{Key: "__yq_fileIndex", Value: int64(doc.FileIndex)},
			{Key: "__yq_data", Value: doc.Value},
		}})
	}
	in := serializeJSON(all, false)
	values, err := runJQProgram(jqExpr, in, false)
	if err != nil {
		return nil, err
	}
	outFmt := "yaml"
	sourcePath := "-"
	inputFmt := "yaml"
	if len(docs) > 0 {
		sourcePath = docs[0].SourcePath
		inputFmt = docs[0].InputFormat
	}
	outFmt, warn := resolvedOutputFormat(opts, inputFmt, sourcePath)
	if warn != "" {
		fmt.Fprintln(os.Stderr, warn)
	}
	out := make([]EvalResult, 0, len(values))
	for _, val := range values {
		out = append(out, EvalResult{Value: val, OutputFormat: outFmt, SourcePath: sourcePath})
	}
	return out, nil
}

func prepareInputBytes(v Value, opts options, inputFormat, path string) ([]byte, string, error) {
	return serializeJSON(v, false), "", nil
}

func preprocessExpression(expr string, opts options) (string, error) {
	if err := checkBadExpression(expr); err != nil {
		return "", err
	}
	expr = strenvRe.ReplaceAllStringFunc(expr, func(match string) string {
		m := strenvRe.FindStringSubmatch(match)
		if len(m) != 2 {
			return match
		}
		b, _ := strconv.Unquote(`"` + os.Getenv(m[1]) + `"`)
		js, _ := jsonQuote(b)
		return js
	})
	var envErr error
	expr = envRe.ReplaceAllStringFunc(expr, func(match string) string {
		if envErr != nil {
			return match
		}
		m := envRe.FindStringSubmatch(match)
		if len(m) != 2 {
			return match
		}
		val, ok := os.LookupEnv(m[1])
		if !ok {
			envErr = fmt.Errorf("value for env variable '%s' not provided in env()", m[1])
			return match
		}
		js, _ := jsonQuote(val)
		return js
	})
	if envErr != nil {
		return "", envErr
	}
	var loadErr error
	expr = loadRe.ReplaceAllStringFunc(expr, func(match string) string {
		if loadErr != nil {
			return match
		}
		m := loadRe.FindStringSubmatch(match)
		if len(m) != 2 {
			return match
		}
		path, err := strconv.Unquote(`"` + m[1] + `"`)
		if err != nil {
			loadErr = err
			return match
		}
		data, err := os.ReadFile(path)
		if err != nil {
			loadErr = err
			return match
		}
		docs, err := parseDocuments(data, autoFormatForPath(path))
		if err != nil {
			loadErr = err
			return match
		}
		var val Value
		if len(docs) == 1 {
			val = docs[0]
		} else {
			val = docs
		}
		return strings.TrimSpace(string(serializeJSON(val, false)))
	})
	if loadErr != nil {
		return "", loadErr
	}
	return expr, nil
}

func translateEvalAll(expr string) (string, error) {
	if m := selectRe.FindStringSubmatch(expr); len(m) == 3 {
		return fmt.Sprintf("([.[] | .__yq_fileIndex as $__yq_fileIndex | .__yq_data | select($__yq_fileIndex == %s)][0]) * ([.[] | .__yq_fileIndex as $__yq_fileIndex | .__yq_data | select($__yq_fileIndex == %s)][0])", m[1], m[2]), nil
	}
	if m := ireduceRe.FindStringSubmatch(expr); len(m) == 3 {
		parts, err := splitTopLevelSemicolon(m[2])
		if err != nil {
			return "", err
		}
		return fmt.Sprintf("reduce (.[] | .__yq_data) as $%s (%s; %s)", m[1], parts[0], parts[1]), nil
	}
	return ".[] | .__yq_fileIndex as $__yq_fileIndex | .__yq_data | " + expr, nil
}

func splitTopLevelSemicolon(s string) ([2]string, error) {
	var parts [2]string
	depth := 0
	inString := false
	escape := false
	for i, r := range s {
		if inString {
			if escape {
				escape = false
				continue
			}
			if r == '\\' {
				escape = true
				continue
			}
			if r == '"' {
				inString = false
			}
			continue
		}
		switch r {
		case '"':
			inString = true
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case ';':
			if depth == 0 {
				parts[0] = strings.TrimSpace(s[:i])
				parts[1] = strings.TrimSpace(s[i+1:])
				if parts[0] == "" || parts[1] == "" {
					return parts, errors.New("invalid ireduce expression")
				}
				return parts, nil
			}
		}
	}
	return parts, errors.New("invalid ireduce expression")
}

func replaceMetaIdentifiers(expr string) string {
	var out strings.Builder
	inString := false
	escape := false
	for i := 0; i < len(expr); {
		ch := expr[i]
		if inString {
			out.WriteByte(ch)
			if escape {
				escape = false
			} else if ch == '\\' {
				escape = true
			} else if ch == '"' {
				inString = false
			}
			i++
			continue
		}
		if ch == '"' {
			inString = true
			out.WriteByte(ch)
			i++
			continue
		}
		if isIdentStart(ch) {
			j := i + 1
			for j < len(expr) && isIdentPart(expr[j]) {
				j++
			}
			ident := expr[i:j]
			prev := byte(0)
			for k := out.Len() - 1; k >= 0; k-- {
				b := out.String()[k]
				if b == ' ' || b == '\n' || b == '\t' || b == '\r' {
					continue
				}
				prev = b
				break
			}
			if (ident == "fileIndex" || ident == "fi") && prev != '.' {
				out.WriteString("$__yq_fileIndex")
			} else {
				out.WriteString(ident)
			}
			i = j
			continue
		}
		out.WriteByte(ch)
		i++
	}
	return out.String()
}

func checkBadExpression(expr string) error {
	inString := false
	escape := false
	var stack []rune
	for _, r := range expr {
		if inString {
			if escape {
				escape = false
				continue
			}
			if r == '\\' {
				escape = true
				continue
			}
			if r == '"' {
				inString = false
			}
			continue
		}
		switch r {
		case '"':
			inString = true
		case '[':
			stack = append(stack, r)
		case ']':
			if len(stack) == 0 {
				return fmt.Errorf("bad expression, could not find matching `[`")
			}
			stack = stack[:len(stack)-1]
		}
	}
	if len(stack) > 0 {
		return fmt.Errorf("bad expression, could not find matching `]`")
	}
	return nil
}

func runJQProgram(program string, input []byte, nullInput bool) ([]Value, error) {
	args := []string{"-c", program}
	if nullInput {
		args = []string{"-n", "-c", program}
	}
	cmd := exec.Command("jq", args...)
	if !nullInput {
		cmd.Stdin = bytes.NewReader(input)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = err.Error()
		}
		if strings.HasPrefix(msg, "jq: ") {
			msg = strings.TrimPrefix(msg, "jq: ")
		}
		return nil, errors.New(msg)
	}
	var values []Value
	sc := bufio.NewScanner(bytes.NewReader(stdout.Bytes()))
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 10*1024*1024)
	for sc.Scan() {
		line := sc.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		val, err := parseJSONBytes(line)
		if err != nil {
			return nil, err
		}
		values = append(values, val)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return values, nil
}

func isIdentStart(b byte) bool {
	return b == '_' || ('A' <= b && b <= 'Z') || ('a' <= b && b <= 'z')
}

func isIdentPart(b byte) bool {
	return isIdentStart(b) || ('0' <= b && b <= '9')
}

func jsonQuote(s string) (string, error) {
	var buf bytes.Buffer
	writeJSON(&buf, s, false, 0)
	return buf.String(), nil
}

