package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"time"
)

const versionString = "yq (https://github.com/mikefarah/yq/) version v4.52.5"

type options struct {
	command                    string
	explicitCommand            bool
	showHelp                   bool
	showVersion                bool
	exitStatus                 bool
	inplace                    bool
	indent                     int
	nullInput                  bool
	noDoc                      bool
	nulOutput                  bool
	prettyPrint                bool
	unwrapScalar               bool
	unwrapScalarExplicit       bool
	inputFormat                string
	inputFormatExplicit        bool
	outputFormat               string
	outputFormatExplicit       bool
	expression                 string
	expressionExplicit         bool
	fromFile                   string
	shellKeySeparator          string
	propertiesArrayBrackets    bool
	propertiesSeparator        string
	luaGlobals                 bool
	luaPrefix                  string
	luaSuffix                  string
	luaUnquoted                bool
	specialHelpOnly            bool
	ignoreNextAsValue          bool
}

func (o options) unwrapScalarValue(yamlDefault bool) bool {
	if o.unwrapScalarExplicit {
		return o.unwrapScalar
	}
	return yamlDefault
}

func main() {
	opts, pos, err := parseCLI(os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		if errors.Is(err, errUnknownFlag) {
			fmt.Fprint(os.Stderr, rootHelpBody)
		}
		os.Exit(1)
	}
	if opts.showVersion {
		fmt.Println(versionString)
		return
	}
	if opts.specialHelpOnly {
		fmt.Print(evalHelpBody)
		return
	}
	if opts.showHelp {
		printHelp(opts)
		return
	}
	if opts.command == "completion" {
		if err := runCompletion(pos); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
		return
	}
	expr, files, ok, err := resolveExpressionAndFiles(opts, pos)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	if !ok {
		if opts.explicitCommand || len(os.Args[1:]) > 0 {
			if opts.command == "eval-all" {
				fmt.Print(evalAllHelpBody)
			} else {
				fmt.Print(evalHelpBody)
			}
		} else {
			fmt.Print(rootHelpBody)
		}
		return
	}
	docs, err := loadInputs(opts, files)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	results, err := evaluate(opts, expr, docs)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
		os.Exit(1)
	}
	if opts.inplace {
		if err := writeInPlace(opts, files, results); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
	} else {
		if err := writeResults(opts, results); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
	}
	if opts.exitStatus && shouldExitNoMatch(results) {
		fmt.Fprintln(os.Stderr, "Error: no matches found")
		os.Exit(1)
	}
}

var errUnknownFlag = errors.New("unknown flag")

func parseCLI(args []string) (options, []string, error) {
	opts := options{
		command:               "eval",
		indent:                2,
		inputFormat:           "auto",
		outputFormat:          "auto",
		shellKeySeparator:     "_",
		propertiesSeparator:   " = ",
		luaPrefix:             "return ",
		luaSuffix:             ";\n",
		unwrapScalar:          true,
		unwrapScalarExplicit:  false,
		propertiesArrayBrackets: false,
	}
	if len(args) == 1 && args[0] == "help" {
		opts.specialHelpOnly = true
		return opts, nil, nil
	}
	if len(args) > 0 {
		switch args[0] {
		case "eval", "e":
			opts.command = "eval"
			opts.explicitCommand = true
			args = args[1:]
		case "eval-all", "ea":
			opts.command = "eval-all"
			opts.explicitCommand = true
			args = args[1:]
		case "completion", "shell-completion":
			opts.command = "completion"
			opts.explicitCommand = true
			args = args[1:]
		}
	}
	var pos []string
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") && arg != "--" {
			name, val, hasValue := strings.Cut(arg[2:], "=")
			getVal := func() (string, error) {
				if hasValue {
					return val, nil
				}
				if i+1 >= len(args) {
					return "", fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				return args[i], nil
			}
			switch name {
			case "help":
				opts.showHelp = true
			case "version":
				opts.showVersion = true
			case "exit-status":
				opts.exitStatus = true
			case "inplace":
				opts.inplace = true
			case "null-input":
				opts.nullInput = true
			case "no-doc":
				opts.noDoc = true
			case "nul-output":
				opts.nulOutput = true
			case "prettyPrint":
				opts.prettyPrint = true
			case "colors", "no-colors", "verbose", "header-preprocess", "csv-auto-parse", "tsv-auto-parse", "string-interpolation", "debug-node-info", "security-disable-env-ops", "security-disable-file-ops", "security-enable-system-operator", "xml-keep-namespace", "xml-raw-token", "xml-skip-directives", "xml-skip-proc-inst", "xml-strict-mode", "yaml-compact-seq-indent", "yaml-fix-merge-anchor-to-spec":
			case "unwrapScalar":
				if hasValue {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return opts, nil, err
					}
					opts.unwrapScalar = b
				} else {
					opts.unwrapScalar = true
				}
				opts.unwrapScalarExplicit = true
			case "indent":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					return opts, nil, err
				}
				opts.indent = n
			case "input-format":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.inputFormat = v
				opts.inputFormatExplicit = true
			case "output-format":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.outputFormat = v
				opts.outputFormatExplicit = true
			case "expression":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.expression = v
				opts.expressionExplicit = true
			case "from-file":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.fromFile = v
			case "shell-key-separator":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.shellKeySeparator = v
			case "properties-array-brackets":
				opts.propertiesArrayBrackets = true
			case "properties-separator":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.propertiesSeparator = v
			case "lua-globals":
				opts.luaGlobals = true
			case "lua-prefix":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.luaPrefix = v
			case "lua-suffix":
				v, err := getVal()
				if err != nil {
					return opts, nil, err
				}
				opts.luaSuffix = v
			case "lua-unquoted":
				opts.luaUnquoted = true
			case "csv-separator", "front-matter", "split-exp", "split-exp-file", "xml-attribute-prefix", "xml-content-name", "xml-directive-name", "xml-proc-inst-prefix":
				_, err := getVal()
				if err != nil {
					return opts, nil, err
				}
			default:
				return opts, nil, fmt.Errorf("%w: --%s", errUnknownFlag, name)
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			shorts := arg[1:]
			for j := 0; j < len(shorts); j++ {
				ch := shorts[j]
				switch ch {
				case 'h':
					opts.showHelp = true
				case 'V':
					opts.showVersion = true
				case 'e':
					opts.exitStatus = true
				case 'i':
					opts.inplace = true
				case 'n':
					opts.nullInput = true
				case 'N':
					opts.noDoc = true
				case '0':
					opts.nulOutput = true
				case 'P':
					opts.prettyPrint = true
				case 'C', 'M', 'v', 'c':
				case 'r':
					opts.unwrapScalar = true
					opts.unwrapScalarExplicit = true
				case 'I', 'p', 'o', 'f', 's':
					var v string
					if j+1 < len(shorts) {
						v = shorts[j+1:]
						j = len(shorts)
					} else {
						if i+1 >= len(args) {
							return opts, nil, fmt.Errorf("flag needs an argument: -%c", ch)
						}
						i++
						v = args[i]
					}
					switch ch {
					case 'I':
						n, err := strconv.Atoi(v)
						if err != nil {
							return opts, nil, err
						}
						opts.indent = n
					case 'p':
						opts.inputFormat = v
						opts.inputFormatExplicit = true
					case 'o':
						opts.outputFormat = v
						opts.outputFormatExplicit = true
					case 'f':
						// accepted, currently ignored
					case 's':
						// accepted, currently ignored
					}
					j = len(shorts)
				default:
					return opts, nil, fmt.Errorf("%w: -%c", errUnknownFlag, ch)
				}
			}
			continue
		}
		pos = append(pos, arg)
	}
	return opts, pos, nil
}

func printHelp(opts options) {
	switch opts.command {
	case "eval":
		fmt.Print(evalHelpFull)
	case "eval-all":
		fmt.Print(evalAllHelpFull)
	case "completion":
		fmt.Print(completionHelpFull)
	default:
		fmt.Print(rootHelpFull)
	}
}

func resolveExpressionAndFiles(opts options, pos []string) (string, []string, bool, error) {
	if opts.command == "completion" {
		return "", pos, true, nil
	}
	var expr string
	if opts.expressionExplicit {
		expr = opts.expression
	} else if opts.fromFile != "" {
		data, err := os.ReadFile(opts.fromFile)
		if err != nil {
			return "", nil, false, err
		}
		expr = strings.TrimRight(string(data), "\n")
	}
	files := []string{}
	if expr == "" {
		if len(pos) > 0 {
			if pos[0] == "-" || fileExists(pos[0]) {
				expr = "."
				files = append(files, pos...)
			} else {
				expr = pos[0]
				files = append(files, pos[1:]...)
			}
		}
	} else {
		files = append(files, pos...)
	}
	if expr == "" && opts.nullInput {
		expr = "."
	}
	if expr == "" && stdinHasData() {
		expr = "."
		files = append(files, "-")
	}
	if expr == "" {
		return "", nil, false, nil
	}
	if len(files) == 0 && !opts.nullInput && !stdinHasData() {
		return "", nil, false, nil
	}
	if len(files) == 0 && !opts.nullInput && stdinHasData() {
		files = []string{"-"}
	}
	return expr, files, true, nil
}

func stdinHasData() bool {
	info, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !info.IsDir()
}

func loadInputs(opts options, files []string) ([]InputDoc, error) {
	if opts.nullInput {
		return nil, nil
	}
	var stdinData []byte
	stdinLoaded := false
	var docs []InputDoc
	for i, file := range files {
		var data []byte
		var err error
		if file == "-" {
			if !stdinLoaded {
				stdinData, err = io.ReadAll(os.Stdin)
				if err != nil {
					return nil, err
				}
				stdinLoaded = true
			}
			data = stdinData
		} else {
			data, err = os.ReadFile(file)
			if err != nil {
				return nil, err
			}
		}
		inFmt := normalizeFormat(opts.inputFormat)
		if !opts.inputFormatExplicit {
			if file == "-" {
				inFmt = "yaml"
			} else {
				inFmt = autoFormatForPath(file)
			}
		}
		parsed, err := parseDocuments(data, inFmt)
		if err != nil {
			return nil, err
		}
		for _, doc := range parsed {
			docs = append(docs, InputDoc{
				FileIndex:   i,
				SourcePath:  file,
				InputFormat: inFmt,
				Value:       doc,
			})
		}
	}
	return docs, nil
}

func writeResults(opts options, results []EvalResult) error {
	for i, result := range results {
		body, err := serializeValue(result.Value, result.OutputFormat, opts, opts.nullInput)
		if err != nil {
			return err
		}
		if opts.nulOutput {
			body = bytesTrimRightNewline(body)
		}
		if result.OutputFormat == "yaml" && !opts.noDoc && len(results) > 1 {
			if _, err := os.Stdout.WriteString("---\n"); err != nil {
				return err
			}
		}
		if _, err := os.Stdout.Write(body); err != nil {
			return err
		}
		if opts.nulOutput {
			if _, err := os.Stdout.Write([]byte{0}); err != nil {
				return err
			}
		} else if i+1 < len(results) && !endsWithNewline(body) {
			if _, err := os.Stdout.Write([]byte{'\n'}); err != nil {
				return err
			}
		}
	}
	return nil
}

func writeInPlace(opts options, files []string, results []EvalResult) error {
	if len(files) == 0 || files[0] == "-" {
		return fmt.Errorf("update file in place of first file given.")
	}
	var buf strings.Builder
	for i, result := range results {
		body, err := serializeValue(result.Value, result.OutputFormat, opts, opts.nullInput)
		if err != nil {
			return err
		}
		if result.OutputFormat == "yaml" && !opts.noDoc && len(results) > 1 {
			buf.WriteString("---\n")
		}
		buf.Write(body)
		if i+1 < len(results) && !endsWithNewline(body) {
			buf.WriteByte('\n')
		}
	}
	return os.WriteFile(files[0], []byte(buf.String()), 0o644)
}

func shouldExitNoMatch(results []EvalResult) bool {
	if len(results) == 0 {
		return true
	}
	for _, result := range results {
		if result.Value == nil {
			return true
		}
		if b, ok := result.Value.(bool); ok && !b {
			return true
		}
	}
	return false
}

func runCompletion(pos []string) error {
	if len(pos) == 0 {
		fmt.Print(completionHelpFull)
		return nil
	}
	switch pos[0] {
	case "bash":
		fmt.Print(completionBash)
	case "zsh":
		fmt.Print(completionZsh)
	case "fish":
		fmt.Print(completionFish)
	case "powershell":
		fmt.Print(completionPowerShell)
	default:
		return fmt.Errorf("unknown shell %q", pos[0])
	}
	return nil
}

func nowWarnTimestamp() string {
	return time.Now().UTC().Format("2006-01-02T15:04:05.000Z")
}

func bytesTrimRightNewline(b []byte) []byte {
	return []byte(strings.TrimRight(string(b), "\n"))
}

func endsWithNewline(b []byte) bool {
	return len(b) > 0 && b[len(b)-1] == '\n'
}

/workspace/formats.go.content:
package main

import (
	"bytes"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type Value any

type OrderedMap struct {
	Entries []Entry
}

type Entry struct {
	Key   string
	Value Value
}

type InputDoc struct {
	FileIndex   int
	SourcePath  string
	InputFormat string
	Value       Value
}

func parseDocuments(data []byte, format string) ([]Value, error) {
	switch normalizeFormat(format) {
	case "yaml", "kyaml", "auto", "":
		return parseYAMLDocuments(data)
	case "json":
		val, err := parseJSONBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "xml":
		val, err := parseXMLBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "props":
		val, err := parsePropsBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	case "ini":
		val, err := parseINIBytes(data)
		if err != nil {
			return nil, err
		}
		return []Value{val}, nil
	default:
		return nil, fmt.Errorf("unsupported input format: %s", format)
	}
}

func parseYAMLDocuments(data []byte) ([]Value, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var docs []Value
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		if len(node.Content) == 0 {
			docs = append(docs, nil)
			continue
		}
		docs = append(docs, yamlNodeToValue(node.Content[0]))
	}
	return docs, nil
}

func yamlNodeToValue(node *yaml.Node) Value {
	switch node.Kind {
	case yaml.DocumentNode:
		if len(node.Content) == 0 {
			return nil
		}
		return yamlNodeToValue(node.Content[0])
	case yaml.MappingNode:
		obj := &OrderedMap{}
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := node.Content[i].Value
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: yamlNodeToValue(node.Content[i+1])})
		}
		return obj
	case yaml.SequenceNode:
		out := make([]Value, 0, len(node.Content))
		for _, child := range node.Content {
			out = append(out, yamlNodeToValue(child))
		}
		return out
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return strings.EqualFold(node.Value, "true")
		case "!!int":
			if v, err := strconv.ParseInt(node.Value, 10, 64); err == nil {
				return v
			}
		case "!!float":
			if v, err := strconv.ParseFloat(node.Value, 64); err == nil {
				return v
			}
		}
		return node.Value
	default:
		return nil
	}
}

func parseJSONBytes(data []byte) (Value, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	val, err := parseJSONValue(dec)
	if err != nil {
		return nil, err
	}
	return val, nil
}

func parseJSONValue(dec *json.Decoder) (Value, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			obj := &OrderedMap{}
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("invalid object key")
				}
				val, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				obj.Entries = append(obj.Entries, Entry{Key: key, Value: val})
			}
			_, err = dec.Token()
			return obj, err
		case '[':
			var arr []Value
			for dec.More() {
				val, err := parseJSONValue(dec)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err = dec.Token()
			return arr, err
		default:
			return nil, fmt.Errorf("unexpected delimiter: %v", t)
		}
	case string:
		return t, nil
	case bool:
		return t, nil
	case nil:
		return nil, nil
	case json.Number:
		if strings.ContainsAny(string(t), ".eE") {
			v, err := t.Float64()
			if err != nil {
				return nil, err
			}
			return v, nil
		}
		v, err := t.Int64()
		if err != nil {
			fv, ferr := t.Float64()
			if ferr != nil {
				return nil, ferr
			}
			return fv, nil
		}
		return v, nil
	default:
		return nil, fmt.Errorf("unsupported json token: %T", tok)
	}
}

type xmlElem struct {
	Name     string
	Attrs    []xml.Attr
	Children []*xmlElem
	Text     string
}

func parseXMLBytes(data []byte) (Value, error) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	var stack []*xmlElem
	var root *xmlElem
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			elem := &xmlElem{Name: t.Name.Local, Attrs: t.Attr}
			if len(stack) > 0 {
				parent := stack[len(stack)-1]
				parent.Children = append(parent.Children, elem)
			} else {
				root = elem
			}
			stack = append(stack, elem)
		case xml.EndElement:
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			if len(stack) == 0 {
				continue
			}
			txt := strings.TrimSpace(string(t))
			if txt == "" {
				continue
			}
			cur := stack[len(stack)-1]
			if cur.Text == "" {
				cur.Text = txt
			} else {
				cur.Text += txt
			}
		}
	}
	if root == nil {
		return &OrderedMap{}, nil
	}
	return &OrderedMap{Entries: []Entry{{Key: root.Name, Value: xmlElemToValue(root)}}}, nil
}

func xmlElemToValue(elem *xmlElem) Value {
	if len(elem.Attrs) == 0 && len(elem.Children) == 0 {
		if elem.Text == "" {
			return ""
		}
		return elem.Text
	}
	obj := &OrderedMap{}
	for _, attr := range elem.Attrs {
		obj.Entries = append(obj.Entries, Entry{Key: "+@" + attr.Name.Local, Value: attr.Value})
	}
	if elem.Text != "" {
		obj.Entries = append(obj.Entries, Entry{Key: "+content", Value: elem.Text})
	}
	grouped := map[string][]Value{}
	order := []string{}
	for _, child := range elem.Children {
		val := xmlElemToValue(child)
		if _, ok := grouped[child.Name]; !ok {
			order = append(order, child.Name)
		}
		grouped[child.Name] = append(grouped[child.Name], val)
	}
	for _, key := range order {
		values := grouped[key]
		if len(values) == 1 {
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: values[0]})
		} else {
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: values})
		}
	}
	return obj
}

func parsePropsBytes(data []byte) (Value, error) {
	root := &OrderedMap{}
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "!") {
			continue
		}
		sep := strings.IndexAny(line, "=:" )
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		assignPath(root, strings.Split(key, "."), val)
	}
	return root, nil
}

func parseINIBytes(data []byte) (Value, error) {
	root := &OrderedMap{}
	cur := root
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			name := strings.TrimSpace(line[1 : len(line)-1])
			sec := &OrderedMap{}
			putEntry(root, name, sec)
			cur = sec
			continue
		}
		sep := strings.IndexAny(line, "=:" )
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		putEntry(cur, key, val)
	}
	return root, nil
}

func putEntry(obj *OrderedMap, key string, value Value) {
	for i := range obj.Entries {
		if obj.Entries[i].Key == key {
			obj.Entries[i].Value = value
			return
		}
	}
	obj.Entries = append(obj.Entries, Entry{Key: key, Value: value})
}

func assignPath(root *OrderedMap, parts []string, value Value) {
	if len(parts) == 0 {
		return
	}
	cur := root
	for i, part := range parts {
		last := i == len(parts)-1
		if last {
			putEntry(cur, part, value)
			return
		}
		var next *OrderedMap
		for j := range cur.Entries {
			if cur.Entries[j].Key == part {
				if existing, ok := cur.Entries[j].Value.(*OrderedMap); ok {
					next = existing
				}
				break
			}
		}
		if next == nil {
			next = &OrderedMap{}
			putEntry(cur, part, next)
		}
		cur = next
	}
}

func normalizeFormat(s string) string {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "", "auto", "a":
		return "auto"
	case "yaml", "y", "kyaml", "ky":
		return "yaml"
	case "json", "j":
		return "json"
	case "xml", "x":
		return "xml"
	case "props", "p":
		return "props"
	case "shell", "s":
		return "shell"
	case "lua", "l":
		return "lua"
	case "ini", "i":
		return "ini"
	default:
		return strings.ToLower(strings.TrimSpace(s))
	}
}

func autoFormatForPath(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".yaml", ".yml":
		return "yaml"
	case ".json":
		return "json"
	case ".xml":
		return "xml"
	case ".properties":
		return "props"
	case ".ini":
		return "ini"
	default:
		return "yaml"
	}
}

func resolvedOutputFormat(opts options, inputFormat, path string) (string, string) {
	if opts.outputFormatExplicit {
		return normalizeFormat(opts.outputFormat), ""
	}
	if opts.inputFormatExplicit {
		out := "yaml"
		if path != "-" {
			auto := autoFormatForPath(path)
			if auto == inputFormat && auto != "yaml" {
				ts := nowWarnTimestamp()
				msg := fmt.Sprintf("time=%s level=WARN msg=\"yq default output is now 'auto' (based on the filename extension). Normally yq would output '%s', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.\"", ts, inputFormat)
				return out, msg
			}
		}
		return out, ""
	}
	if path != "" && path != "-" {
		return autoFormatForPath(path), ""
	}
	return "yaml", ""
}

func serializeValue(v Value, format string, opts options, nullInput bool) ([]byte, error) {
	switch normalizeFormat(format) {
	case "json":
		unwrap := opts.unwrapScalarValue(false)
		if isScalar(v) && unwrap {
			return []byte(rawScalarString(v) + "\n"), nil
		}
		return serializeJSON(v, true), nil
	case "yaml":
		unwrap := opts.unwrapScalarValue(true)
		if isScalar(v) && unwrap {
			if nullInput && v == nil {
				return []byte("\n"), nil
			}
			return []byte(rawScalarString(v) + "\n"), nil
		}
		return serializeYAML(v, opts.indent)
	case "xml":
		return serializeXML(v)
	case "props":
		return []byte(renderProps(v, opts.propertiesSeparator, opts.propertiesArrayBrackets)), nil
	case "shell":
		return []byte(renderShell(v, opts.shellKeySeparator)), nil
	case "ini":
		return []byte(renderINI(v)), nil
	case "lua":
		return []byte(renderLua(v, opts.luaPrefix, opts.luaSuffix, opts.luaUnquoted, opts.luaGlobals)), nil
	default:
		return nil, fmt.Errorf("unsupported output format: %s", format)
	}
}

func serializeYAML(v Value, indent int) ([]byte, error) {
	doc := &yaml.Node{Kind: yaml.DocumentNode}
	doc.Content = []*yaml.Node{valueToYAMLNode(v)}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(indent)
	if err := enc.Encode(doc.Content[0]); err != nil {
		return nil, err
	}
	_ = enc.Close()
	return buf.Bytes(), nil
}

func valueToYAMLNode(v Value) *yaml.Node {
	switch x := v.(type) {
	case nil:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
	case string:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: x}
	case bool:
		if x {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "true"}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "false"}
	case int64:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatInt(x, 10)}
	case float64:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(x, 'f', -1, 64)}
	case []Value:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, item := range x {
			n.Content = append(n.Content, valueToYAMLNode(item))
		}
		return n
	case *OrderedMap:
		n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, entry := range x.Entries {
			n.Content = append(n.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: entry.Key}, valueToYAMLNode(entry.Value))
		}
		return n
	default:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: fmt.Sprint(x)}
	}
}

func serializeJSON(v Value, pretty bool) []byte {
	var buf bytes.Buffer
	writeJSON(&buf, v, pretty, 0)
	buf.WriteByte('\n')
	return buf.Bytes()
}

func writeJSON(buf *bytes.Buffer, v Value, pretty bool, depth int) {
	indent := strings.Repeat("  ", depth)
	nextIndent := strings.Repeat("  ", depth+1)
	switch x := v.(type) {
	case nil:
		buf.WriteString("null")
	case string:
		b, _ := json.Marshal(x)
		buf.Write(b)
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case int64:
		buf.WriteString(strconv.FormatInt(x, 10))
	case float64:
		buf.WriteString(strconv.FormatFloat(x, 'f', -1, 64))
	case []Value:
		if len(x) == 0 {
			buf.WriteString("[]")
			return
		}
		if !pretty {
			buf.WriteByte('[')
			for i, item := range x {
				if i > 0 {
					buf.WriteByte(',')
				}
				writeJSON(buf, item, false, depth+1)
			}
			buf.WriteByte(']')
			return
		}
		buf.WriteString("[\n")
		for i, item := range x {
			buf.WriteString(nextIndent)
			writeJSON(buf, item, true, depth+1)
			if i+1 < len(x) {
				buf.WriteByte(',')
			}
			buf.WriteByte('\n')
		}
		buf.WriteString(indent)
		buf.WriteByte(']')
	case *OrderedMap:
		if len(x.Entries) == 0 {
			buf.WriteString("{}")
			return
		}
