func serializeYAML(v Value, indent int) ([]byte, error) {
	doc := &yaml.Node{Kind: yaml.DocumentNode}
	doc.Content = []*yaml.Node{valueToYAMLNode(v)}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
