		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(x, 'f', -1, 64)}
	case []Value:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
