func serializeJSON(v Value, pretty bool) []byte {
	var buf bytes.Buffer
	writeJSON(&buf, v, pretty, 0)
	buf.WriteByte('\n')
	return buf.Bytes()
}

func writeJSON(buf *bytes.Buffer, v Value, pretty bool, depth int) {
	indent := strings.Repeat("  ", depth)
	nextIndent := strings.Repeat("  ", depth+1)
	switch x := v.(type) {
	case nil:
		buf.WriteString("null")
	case string:
		b, _ := json.Marshal(x)
		buf.Write(b)
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case int64:
		buf.WriteString(strconv.FormatInt(x, 10))
	case float64:
		buf.WriteString(strconv.FormatFloat(x, 'f', -1, 64))
	case []Value:
		if len(x) == 0 {
			buf.WriteString("[]")
			return
		}
		if !pretty {
			buf.WriteByte('[')
			for i, item := range x {
				if i > 0 {
					buf.WriteByte(',')
				}
				writeJSON(buf, item, false, depth+1)
			}
			buf.WriteByte(']')
			return
		}
		buf.WriteString("[\n")
		for i, item := range x {
			buf.WriteString(nextIndent)
			writeJSON(buf, item, true, depth+1)
			if i+1 < len(x) {
				buf.WriteByte(',')
			}
			buf.WriteByte('\n')
		}
		buf.WriteString(indent)
		buf.WriteByte(']')
	case *OrderedMap:
		if len(x.Entries) == 0 {
			buf.WriteString("{}")
			return
		}
		if !pretty {
			buf.WriteByte('{')
			for i, entry := range x.Entries {
				if i > 0 {
					buf.WriteByte(',')
				}
				k, _ := json.Marshal(entry.Key)
				buf.Write(k)
				buf.WriteByte(':')
				writeJSON(buf, entry.Value, false, depth+1)
			}
			buf.WriteByte('}')
			return
		}
		buf.WriteString("{\n")
		for i, entry := range x.Entries {
			buf.WriteString(nextIndent)
			k, _ := json.Marshal(entry.Key)
			buf.Write(k)
			buf.WriteString(": ")
			writeJSON(buf, entry.Value, true, depth+1)
			if i+1 < len(x.Entries) {
				buf.WriteByte(',')
			}
			buf.WriteByte('\n')
		}
		buf.WriteString(indent)
		buf.WriteByte('}')
	default:
		b, _ := json.Marshal(fmt.Sprint(x))
		buf.Write(b)
	}
}

func serializeXML(v Value) ([]byte, error) {
	var buf bytes.Buffer
	switch x := v.(type) {
	case *OrderedMap:
		for _, entry := range x.Entries {
			if err := writeXMLNode(&buf, entry.Key, entry.Value, 0); err != nil {
				return nil, err
			}
		}
	default:
		return nil, fmt.Errorf("xml output requires an object root")
	}
	return buf.Bytes(), nil
}

func writeXMLNode(buf *bytes.Buffer, name string, v Value, depth int) error {
	indent := strings.Repeat("  ", depth)
	switch x := v.(type) {
	case []Value:
		for _, item := range x {
			if err := writeXMLNode(buf, name, item, depth); err != nil {
				return err
			}
		}
		return nil
	case *OrderedMap:
		attrs := []Entry{}
		children := []Entry{}
		var text string
		for _, entry := range x.Entries {
			switch {
			case strings.HasPrefix(entry.Key, "+@"):
				attrs = append(attrs, entry)
			case entry.Key == "+content":
				text = fmt.Sprint(entry.Value)
			default:
				children = append(children, entry)
			}
		}
		buf.WriteString(indent)
		buf.WriteByte('<')
		buf.WriteString(name)
		for _, attr := range attrs {
			buf.WriteByte(' ')
			buf.WriteString(strings.TrimPrefix(attr.Key, "+@"))
			buf.WriteString(`="`)
			xml.EscapeText(buf, []byte(fmt.Sprint(attr.Value)))
			buf.WriteByte('"')
		}
		if text == "" && len(children) == 0 {
			buf.WriteString("></")
			buf.WriteString(name)
			buf.WriteString(">\n")
			return nil
		}
		if len(children) == 0 {
			buf.WriteByte('>')
			xml.EscapeText(buf, []byte(text))
			buf.WriteString("</")
			buf.WriteString(name)
			buf.WriteString(">\n")
			return nil
		}
		buf.WriteString(">\n")
		if text != "" {
			buf.WriteString(strings.Repeat("  ", depth+1))
			xml.EscapeText(buf, []byte(text))
			buf.WriteByte('\n')
		}
		for _, child := range children {
			if err := writeXMLNode(buf, child.Key, child.Value, depth+1); err != nil {
				return err
			}
		}
		buf.WriteString(indent)
		buf.WriteString("</")
		buf.WriteString(name)
		buf.WriteString(">\n")
		return nil
	default:
		buf.WriteString(indent)
		buf.WriteByte('<')
		buf.WriteString(name)
		buf.WriteByte('>')
		xml.EscapeText(buf, []byte(fmt.Sprint(x)))
		buf.WriteString("</")
		buf.WriteString(name)
		buf.WriteString(">\n")
		return nil
	}
