func renderProps(v Value, sep string, arrayBrackets bool) string {
	if sep == "" {
		sep = " = "
	}
	lines := flattenValue(v, "", ".", arrayBrackets)
	var buf strings.Builder
	for i, line := range lines {
		if i > 0 {
			buf.WriteByte('\n')
		}
		buf.WriteString(line.Key)
		buf.WriteString(sep)
		buf.WriteString(line.Value)
	}
	if buf.Len() > 0 {
		buf.WriteByte('\n')
	}
	return buf.String()
}

func renderShell(v Value, sep string) string {
	if sep == "" {
		sep = "_"
	}
	lines := flattenValue(v, "", sep, false)
	var buf strings.Builder
	for i, line := range lines {
		if i > 0 {
			buf.WriteByte('\n')
		}
		buf.WriteString(line.Key)
		buf.WriteByte('=')
		buf.WriteString(shellEscape(line.Value))
	}
	if buf.Len() > 0 {
		buf.WriteByte('\n')
	}
	return buf.String()
}

func renderINI(v Value) string {
	root, ok := v.(*OrderedMap)
	if !ok {
		return ""
	}
	var buf strings.Builder
	firstSection := true
	for _, entry := range root.Entries {
		child, ok := entry.Value.(*OrderedMap)
		if !ok {
			continue
		}
		if !firstSection {
			buf.WriteByte('\n')
		}
		firstSection = false
		buf.WriteString("[")
		buf.WriteString(entry.Key)
		buf.WriteString("]\n")
		for _, kv := range child.Entries {
			if isScalar(kv.Value) {
				buf.WriteString(kv.Key)
				buf.WriteString(" = ")
				buf.WriteString(rawScalarString(kv.Value))
				buf.WriteByte('\n')
			}
		}
	}
	return buf.String()
}

func renderLua(v Value, prefix, suffix string, unquoted, globals bool) string {
	if prefix == "" {
		prefix = "return "
	}
	if suffix == "" {
		suffix = ";\n"
	}
	if globals {
		root, ok := v.(*OrderedMap)
		if !ok {
			return ""
		}
		var buf strings.Builder
		for _, entry := range root.Entries {
			buf.WriteString(luaKey(entry.Key, unquoted))
			buf.WriteString(" = ")
			buf.WriteString(luaValue(entry.Value, 0, unquoted))
			buf.WriteString(suffix)
		}
		return buf.String()
	}
	return prefix + luaValue(v, 0, unquoted) + suffix
}

func luaValue(v Value, depth int, unquoted bool) string {
	indent := strings.Repeat("\t", depth)
	nextIndent := strings.Repeat("\t", depth+1)
	switch x := v.(type) {
	case nil:
		return "nil"
	case string:
		b, _ := json.Marshal(x)
		return string(b)
	case bool:
		if x {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64)
	case []Value:
		if len(x) == 0 {
			return "{}"
		}
		var buf strings.Builder
		buf.WriteString("{\n")
		for _, item := range x {
			buf.WriteString(nextIndent)
			buf.WriteString(luaValue(item, depth+1, unquoted))
			buf.WriteString(",\n")
		}
		buf.WriteString(indent)
		buf.WriteString("}")
		return buf.String()
	case *OrderedMap:
		if len(x.Entries) == 0 {
			return "{}"
		}
		var buf strings.Builder
		buf.WriteString("{\n")
		for _, entry := range x.Entries {
			buf.WriteString(nextIndent)
			buf.WriteString(luaKey(entry.Key, unquoted))
			buf.WriteString(" = ")
			buf.WriteString(luaValue(entry.Value, depth+1, unquoted))
			buf.WriteString(";\n")
		}
		buf.WriteString(indent)
		buf.WriteString("}")
		return buf.String()
	default:
		b, _ := json.Marshal(fmt.Sprint(x))
		return string(b)
	}
}

func luaKey(key string, unquoted bool) string {
	if unquoted && isLuaIdentifier(key) {
		return key
	}
	b, _ := json.Marshal(key)
	return "[" + string(b) + "]"
}

func isLuaIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !(r == '_' || ('A' <= r && r <= 'Z') || ('a' <= r && r <= 'z')) {
				return false
			}
			continue
		}
		if !(r == '_' || ('A' <= r && r <= 'Z') || ('a' <= r && r <= 'z') || ('0' <= r && r <= '9')) {
			return false
		}
	}
	return true
}

type flatLine struct {
	Key   string
	Value string
}

func flattenValue(v Value, prefix, sep string, arrayBrackets bool) []flatLine {
	switch x := v.(type) {
	case *OrderedMap:
		var out []flatLine
		for _, entry := range x.Entries {
			key := entry.Key
			if prefix != "" {
				key = prefix + sep + key
			}
			out = append(out, flattenValue(entry.Value, key, sep, arrayBrackets)...)
		}
		return out
	case []Value:
		var out []flatLine
		for i, item := range x {
			var key string
			if arrayBrackets {
				key = fmt.Sprintf("%s[%d]", prefix, i)
			} else {
				key = fmt.Sprintf("%s%s%d", prefix, sep, i)
			}
			if prefix == "" {
				key = strconv.Itoa(i)
			}
			out = append(out, flattenValue(item, key, sep, arrayBrackets)...)
		}
		return out
	default:
		return []flatLine{{Key: prefix, Value: rawScalarString(x)}}
	}
}

