+				more, err := p.parseMapping(leadingSpaces(p.lines[p.index]))
+				if err != nil {
+					return nil, err
+				}
+				if extra, ok := more.(*OrderedMap); ok {
+					obj.Entries = append(obj.Entries, extra.Entries...)
+				}
+			}
+			out = append(out, obj)
+			continue
+		}
+		val, err := parseYAMLScalarOrFlow(content)
+		if err != nil {
+			return nil, err
+		}
+		out = append(out, val)
+	}
+	return out, nil
+}
+
+func (p *yamlLiteParser) parseMapping(indent int) (Value, error) {
+	obj := &OrderedMap{}
+	for {
+		p.skipBlank()
+		if p.index >= len(p.lines) {
+			break
+		}
+		line := p.lines[p.index]
+		curIndent := leadingSpaces(line)
+		if curIndent < indent {
+			break
+		}
+		if curIndent > indent {
+			return nil, fmt.Errorf("yaml parse error near %q", strings.TrimSpace(line))
+		}
+		trimmed := strings.TrimSpace(line)
+		if strings.HasPrefix(trimmed, "- ") {
+			break
+		}
+		key, rest, ok := splitYAMLKeyValue(trimmed)
+		if !ok {
+			return nil, fmt.Errorf("yaml parse error near %q", trimmed)
+		}
+		p.index++
+		var val Value
+		if rest == "" {
+			p.skipBlank()
+			if p.index < len(p.lines) && leadingSpaces(p.lines[p.index]) > indent {
+				var err error
+				val, err = p.parseBlock(leadingSpaces(p.lines[p.index]))
+				if err != nil {
+					return nil, err
+				}
+			}
+		} else {
+			var err error
+			val, err = parseYAMLScalarOrFlow(rest)
+			if err != nil {
+				return nil, err
+			}
+		}
+		obj.Entries = append(obj.Entries, Entry{Key: key, Value: val})
+	}
+	return obj, nil
+}
+
+func (p *yamlLiteParser) skipBlank() {
+	for p.index < len(p.lines) {
+		trimmed := strings.TrimSpace(p.lines[p.index])
+		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
+			p.index++
+			continue
+		}
+		break
+	}
+}
+
+func splitYAMLKeyValue(s string) (string, string, bool) {
+	inSingle := false
+	inDouble := false
+	escape := false
+	for i := 0; i < len(s); i++ {
+		ch := s[i]
+		if inDouble {
+			if escape {
+				escape = false
+				continue
+			}
+			if ch == '\\' {
+				escape = true
+				continue
+			}
+			if ch == '"' {
+				inDouble = false
+			}
+			continue
+		}
+		if inSingle {
+			if ch == '\'' {
+				inSingle = false
+			}
+			continue
+		}
+		switch ch {
+		case '"':
+			inDouble = true
+		case '\'':
+			inSingle = true
+		case ':':
+			key := strings.TrimSpace(s[:i])
+			rest := strings.TrimSpace(s[i+1:])
+			return key, rest, key != ""
+		}
+	}
+	return "", "", false
+}
+
+func parseYAMLScalarOrFlow(s string) (Value, error) {
+	s = strings.TrimSpace(s)
+	switch s {
+	case "":
+		return "", nil
+	case "null", "~":
+		return nil, nil
+	case "true":
+		return true, nil
+	case "false":
+		return false, nil
+	case "[]":
+		return []Value{}, nil
+	case "{}":
+		return &OrderedMap{}, nil
+	}
+	if strings.HasPrefix(s, `"`) && strings.HasSuffix(s, `"`) {
+		return strconv.Unquote(s)
+	}
+	if strings.HasPrefix(s, `'`) && strings.HasSuffix(s, `'`) && len(s) >= 2 {
+		return strings.ReplaceAll(s[1:len(s)-1], `''`, `'`), nil
+	}
+	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
+		body := strings.TrimSpace(s[1 : len(s)-1])
+		if body == "" {
+			return []Value{}, nil
+		}
+		parts := splitTopLevelCSV(body)
+		out := make([]Value, 0, len(parts))
+		for _, part := range parts {
+			val, err := parseYAMLScalarOrFlow(part)
+			if err != nil {
+				return nil, err
+			}
+			out = append(out, val)
+		}
+		return out, nil
+	}
+	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
+		body := strings.TrimSpace(s[1 : len(s)-1])
+		obj := &OrderedMap{}
+		if body == "" {
+			return obj, nil
+		}
+		for _, part := range splitTopLevelCSV(body) {
+			key, rest, ok := splitYAMLKeyValue(part)
+			if !ok {
+				return nil, fmt.Errorf("yaml parse error near %q", s)
+			}
+			val, err := parseYAMLScalarOrFlow(rest)
+			if err != nil {
+				return nil, err
+			}
+			obj.Entries = append(obj.Entries, Entry{Key: key, Value: val})
+		}
+		return obj, nil
+	}
+	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
+		return i, nil
+	}
+	if f, err := strconv.ParseFloat(s, 64); err == nil && strings.ContainsAny(s, ".eE") {
+		return f, nil
+	}
+	return s, nil
+}
+
+func splitTopLevelCSV(s string) []string {
+	var parts []string
+	start := 0
+	depth := 0
+	inSingle := false
+	inDouble := false
+	escape := false
+	for i := 0; i < len(s); i++ {
+		ch := s[i]
+		if inDouble {
+			if escape {
+				escape = false
+				continue
+			}
+			if ch == '\\' {
+				escape = true
+				continue
+			}
+			if ch == '"' {
+				inDouble = false
+			}
+			continue
+		}
+		if inSingle {
+			if ch == '\'' {
+				inSingle = false
+			}
+			continue
+		}
+		switch ch {
+		case '"':
+			inDouble = true
+		case '\'':
+			inSingle = true
+		case '[', '{', '(':
+			depth++
+		case ']', '}', ')':
+			if depth > 0 {
+				depth--
+			}
+		case ',':
+			if depth == 0 {
+				parts = append(parts, strings.TrimSpace(s[start:i]))
+				start = i + 1
+			}
+		}
+	}
+	parts = append(parts, strings.TrimSpace(s[start:]))
+	return parts
+}
+
+func leadingSpaces(s string) int {
+	n := 0
+	for n < len(s) && s[n] == ' ' {
+		n++
+	}
+	return n
+}
+
+func writeYAML(buf *bytes.Buffer, v Value, depth, indent int) {
+	pad := strings.Repeat(" ", depth)
+	switch x := v.(type) {
+	case *OrderedMap:
+		for _, entry := range x.Entries {
+			if isScalar(entry.Value) || isEmptyCollection(entry.Value) {
+				buf.WriteString(pad)
+				buf.WriteString(yamlString(entry.Key))
+				buf.WriteString(": ")
+				buf.WriteString(yamlScalar(entry.Value))
+				buf.WriteByte('\n')
+				continue
+			}
+			buf.WriteString(pad)
+			buf.WriteString(yamlString(entry.Key))
+			buf.WriteString(":\n")
+			writeYAML(buf, entry.Value, depth+indent, indent)
+		}
+	case []Value:
+		for _, item := range x {
+			if isScalar(item) || isEmptyCollection(item) {
+				buf.WriteString(pad)
+				buf.WriteString("- ")
+				buf.WriteString(yamlScalar(item))
+				buf.WriteByte('\n')
+				continue
+			}
+			if obj, ok := item.(*OrderedMap); ok && len(obj.Entries) > 0 && (isScalar(obj.Entries[0].Value) || isEmptyCollection(obj.Entries[0].Value)) {
+				buf.WriteString(pad)
+				buf.WriteString("- ")
+				buf.WriteString(yamlString(obj.Entries[0].Key))
+				buf.WriteString(": ")
+				buf.WriteString(yamlScalar(obj.Entries[0].Value))
+				buf.WriteByte('\n')
+				if len(obj.Entries) > 1 {
+					writeYAML(buf, &OrderedMap{Entries: obj.Entries[1:]}, depth+indent, indent)
+				}
+				continue
+			}
+			buf.WriteString(pad)
+			buf.WriteString("-\n")
+			writeYAML(buf, item, depth+indent, indent)
+		}
+	default:
+		buf.WriteString(pad)
+		buf.WriteString(yamlScalar(v))
+		buf.WriteByte('\n')
+	}
+}
+
+func yamlScalar(v Value) string {
+	switch x := v.(type) {
+	case nil:
+		return "null"
+	case string:
+		return yamlString(x)
+	case bool:
+		if x {
+			return "true"
+		}
+		return "false"
+	case int64:
+		return strconv.FormatInt(x, 10)
+	case float64:
+		return strconv.FormatFloat(x, 'f', -1, 64)
+	case []Value:
+		return "[]"
+	case *OrderedMap:
+		return "{}"
+	default:
+		return yamlString(fmt.Sprint(x))
+	}
+}
+
+func yamlString(s string) string {
+	if s == "" {
+		return `""`
+	}
+	if s == "null" || s == "true" || s == "false" || strings.HasPrefix(s, "-") || strings.HasPrefix(s, "{") || strings.HasPrefix(s, "[") || strings.Contains(s, ": ") || strings.ContainsAny(s, "#\n\r\t\"") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
+		b, _ := json.Marshal(s)
+		return string(b)
+	}
+	return s
+}
+
+func isEmptyCollection(v Value) bool {
+	switch x := v.(type) {
+	case []Value:
+		return len(x) == 0
+	case *OrderedMap:
+		return len(x.Entries) == 0
+	default:
+		return false
+	}
